import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

def visualize_results():
    """
    Reads the hyperparameter tuning results from a CSV file and generates a heatmap
    to visualize the performance of different parameter combinations.
    """
    # Read the data generated by the C program
    try:
        df = pd.read_csv("hyperparameter_results.csv")
    except FileNotFoundError:
        print("Error: hyperparameter_results.csv not found.")
        print("Please run the C hyperparameter tuner program first to generate the file.")
        return

    # Create a pivot table to structure the data for the heatmap.
    # It calculates the average accuracy for each combination.
    pivot_table = df.pivot_table(
        values='Accuracy', 
        index='LearningRate', 
        columns='Epochs', 
        aggfunc='mean'
    )

    # Create the heatmap plot
    plt.figure(figsize=(12, 8))
    sns.heatmap(
        pivot_table, 
        annot=True,     # Display the accuracy values on the heatmap cells
        fmt=".2f",      # Format the numbers to two decimal places
        cmap="viridis", # Use a visually appealing color scheme
        linewidths=.5   # Add thin lines between cells
    )

    # Add titles and labels for clarity
    plt.title('Hyperparameter Tuning for Perceptron (Versicolor vs. Virginica)', fontsize=16)
    plt.xlabel('Number of Epochs', fontsize=12)
    plt.ylabel('Learning Rate', fontsize=12)
    plt.gca().invert_yaxis() # Invert y-axis to show higher learning rates at the top

    # Save the plot to a file and then display it
    plt.savefig("hyperparameter_heatmap.png")
    print("Heatmap plot saved to hyperparameter_heatmap.png")
    plt.show()

if __name__ == '__main__':
    visualize_results()